import re
from pathlib import Path
pattern = re.compile('spam')
for path in sorted(Path('.').glob('*.txt')):
    lines = path.read_text().splitlines()
    for number, line in enumerate(lines, 1):
        if pattern.search(line):
            print(path.name, number, line)
